SELECT T1.CALENDAR_ID calendarId , T1.CDATE cdate , T1.IS_HOLIDAY isHoliday , T1.UPDATE_TIME updateTime, T1.UPDATE_USER updateUser, T2.CALENDAR_NAME calendarName, T1.STATUS status, T1.ERR_MSG errMsg, null orgData from MST_HOLIDAY T1 left join MST_CALENDAR_INFO T2 on T1.CALENDAR_ID = T2.CALENDAR_ID
#{item}
and T1.IS_HOLIDAY = #{ishDay}
and T1.CDATE >= #{startDate}
and T1.CDATE <= #{endDate}
and T1.STATUS = #{status}
union all SELECT T1.CALENDAR_ID calendarId , T1.CDATE cdate , T1.IS_HOLIDAY isHoliday , T1.UPDATE_TIME updateTime, T1.UPDATE_USER updateUser, T2.CALENDAR_NAME calendarName, T1.STATUS status, T1.ERR_MSG errMsg, T1.ORG_DATA orgData from MST_HOLIDAY_ERRODATA T1 left join MST_CALENDAR_INFO T2 on T1.CALENDAR_ID = T2.CALENDAR_ID
#{item}
and T1.IS_HOLIDAY = #{ishDay}
and T1.CDATE >= #{startDate}
and T1.CDATE <= #{endDate}
and T1.STATUS = #{status}
ORDER BY calendarId ASC,cdate DESC

select calendar_Id calendarId, calendar_Name calendarName from MST_CALENDAR_INFO
IS_TRADE_CALENDAR = #{no}
AND calendar_Id = #{calendarType}
ORDER BY calendarId ASC

